                        { alwaysVisible: false, state: 'todo' },
                        { alwaysVisible: false, state: 'done' },
                    ]}
                    statusColors={new Map([['todo', '#111111'], ['done', '#222222']])}
                    {...overrides}
                />
            </div>
        </AppThemeProvider>,
    )
}

