function initialsFor(value: string) {
    const parts = value.trim().split(/\s+/u)
    if (parts.length === 1 && parts[0].length <= 2) return parts[0].toUpperCase()

    return (parts.map((part) => part[0]).join('') || '?').slice(0, 2).toUpperCase()
